  "store_id" TEXT NOT NULL,
  "user_id" TEXT,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "csv_data" TEXT NOT NULL,
  "update_existing" INTEGER NOT NULL DEFAULT 1,
  "total" INTEGER NOT NULL DEFAULT 0,
  "processed" INTEGER NOT NULL DEFAULT 0,
  "created" INTEGER NOT NULL DEFAULT 0,
  "updated" INTEGER NOT NULL DEFAULT 0,
  "failed" INTEGER NOT NULL DEFAULT 0,
  "errors" TEXT,
  "error_message" TEXT,
  "started_at" INTEGER,
  "completed_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "bulk_import_jobs_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "bulk_import_jobs_status_chk" CHECK ("status" IN ('queued', 'running', 'completed', 'failed')),
  CONSTRAINT "bulk_import_jobs_update_existing_chk" CHECK ("update_existing" IN (0, 1)),
  CONSTRAINT "bulk_import_jobs_errors_chk" CHECK ("errors" IS NULL OR (json_valid("errors")))
);
CREATE INDEX IF NOT EXISTS "bulk_import_jobs_store_id_created_at_idx" ON "bulk_import_jobs" ("store_id", "created_at" DESC);
CREATE INDEX IF NOT EXISTS "bulk_import_jobs_status_idx" ON "bulk_import_jobs" ("status");

CREATE TABLE IF NOT EXISTS "bundle_items" (
  "id" TEXT NOT NULL,
  "bundle_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "variant_id" TEXT,
  "quantity" INTEGER NOT NULL,
  CONSTRAINT "bundle_items_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "bundle_items_bundle_id_fkey" FOREIGN KEY ("bundle_id") REFERENCES "bundles" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "bundle_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "bundle_items_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "bundle_items_quantity_range" CHECK (quantity >= 1 AND quantity <= 1000)
);
CREATE UNIQUE INDEX IF NOT EXISTS "bundle_items_bundle_id_product_id_variant_id_key" ON "bundle_items" ("bundle_id", "product_id", "variant_id");
CREATE INDEX IF NOT EXISTS "bundle_items_bundle_id_idx" ON "bundle_items" ("bundle_id");
CREATE INDEX IF NOT EXISTS "bundle_items_product_id_idx" ON "bundle_items" ("product_id");
CREATE INDEX IF NOT EXISTS "bundle_items_variant_id_idx" ON "bundle_items" ("variant_id");

CREATE TABLE IF NOT EXISTS "bundles" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "name_ar" TEXT,
  "slug" TEXT NOT NULL,
  "description" TEXT,
  "description_ar" TEXT,
  "image" TEXT,
  "pricing_type" TEXT NOT NULL,
  "pricing_value" INTEGER NOT NULL,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "starts_at" INTEGER,
  "expires_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "bundles_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "bundles_pricing_type_chk" CHECK ("pricing_type" IN ('fixed_price', 'percentage', 'fixed')),
  CONSTRAINT "bundles_is_active_chk" CHECK ("is_active" IN (0, 1))
);
CREATE UNIQUE INDEX IF NOT EXISTS "bundles_store_id_slug_key" ON "bundles" ("store_id", "slug");
CREATE INDEX IF NOT EXISTS "bundles_store_id_is_active_idx" ON "bundles" ("store_id", "is_active");

CREATE TABLE IF NOT EXISTS "campaign_recipients" (
  "id" TEXT NOT NULL,
  "campaign_id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "subscriber_id" TEXT,
  "customer_id" TEXT,
  "locale" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "provider_message_id" TEXT,
  "error" TEXT,
  "sent_at" INTEGER,
  "unsubscribed_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "campaign_recipients_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "campaign_recipients_campaign_id_fkey" FOREIGN KEY ("campaign_id") REFERENCES "campaigns" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "campaign_recipients_subscriber_id_fkey" FOREIGN KEY ("subscriber_id") REFERENCES "newsletter_subscribers" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "campaign_recipients_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "campaign_recipients_status_chk" CHECK ("status" IN ('queued', 'sent', 'failed', 'bounced', 'unsubscribed'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "campaign_recipients_campaign_id_email_key" ON "campaign_recipients" ("campaign_id", "email");
CREATE INDEX IF NOT EXISTS "campaign_recipients_campaign_id_status_idx" ON "campaign_recipients" ("campaign_id", "status");
CREATE INDEX IF NOT EXISTS "campaign_recipients_store_id_status_sent_at_idx" ON "campaign_recipients" ("store_id", "status", "sent_at");
CREATE INDEX IF NOT EXISTS "campaign_recipients_subscriber_id_idx" ON "campaign_recipients" ("subscriber_id");
CREATE INDEX IF NOT EXISTS "campaign_recipients_customer_id_idx" ON "campaign_recipients" ("customer_id");

CREATE TABLE IF NOT EXISTS "campaigns" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "subject_ar" TEXT,
  "body_html" TEXT NOT NULL,
  "body_html_ar" TEXT,
  "locale_strategy" TEXT NOT NULL DEFAULT 'subscriber',
  "audience" TEXT NOT NULL DEFAULT '{"source":"newsletter"}',
  "status" TEXT NOT NULL DEFAULT 'draft',
  "scheduled_at" INTEGER,
  "sent_at" INTEGER,
  "recipient_count" INTEGER NOT NULL DEFAULT 0,
  "sent_count" INTEGER NOT NULL DEFAULT 0,
  "failed_count" INTEGER NOT NULL DEFAULT 0,
  "last_error" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "campaigns_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "campaigns_audience_chk" CHECK (json_valid("audience")),
  CONSTRAINT "campaigns_status_chk" CHECK ("status" IN ('draft', 'scheduled', 'sending', 'sent', 'cancelled', 'failed'))
);
CREATE INDEX IF NOT EXISTS "campaigns_store_id_created_at_idx" ON "campaigns" ("store_id", "created_at");

CREATE TABLE IF NOT EXISTS "cart_bundles" (
  "id" TEXT NOT NULL,
  "cart_id" TEXT NOT NULL,
  "bundle_id" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL DEFAULT 1,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "cart_bundles_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "cart_bundles_cart_id_fkey" FOREIGN KEY ("cart_id") REFERENCES "carts" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "cart_bundles_bundle_id_fkey" FOREIGN KEY ("bundle_id") REFERENCES "bundles" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "cart_bundles_cart_id_bundle_id_key" ON "cart_bundles" ("cart_id", "bundle_id");
CREATE INDEX IF NOT EXISTS "cart_bundles_bundle_id_idx" ON "cart_bundles" ("bundle_id");

CREATE TABLE IF NOT EXISTS "cart_items" (
  "id" TEXT NOT NULL,
  "cart_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "variant_id" TEXT,
  "quantity" INTEGER NOT NULL DEFAULT 1,
  "note" TEXT,
  "quoted_unit_price" INTEGER,
  "quoted_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "cart_items_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "cart_items_cart_id_fkey" FOREIGN KEY ("cart_id") REFERENCES "carts" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "cart_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "cart_items_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS "cart_items_cart_id_idx" ON "cart_items" ("cart_id");
CREATE INDEX IF NOT EXISTS "cart_items_product_id_idx" ON "cart_items" ("product_id");
CREATE INDEX IF NOT EXISTS "cart_items_variant_id_idx" ON "cart_items" ("variant_id");
CREATE UNIQUE INDEX IF NOT EXISTS "cart_items_line_no_variant" ON "cart_items" ("cart_id", "product_id", (COALESCE("note", ''))) WHERE "variant_id" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "cart_items_line_with_variant" ON "cart_items" ("cart_id", "product_id", "variant_id", (COALESCE("note", ''))) WHERE "variant_id" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "carts" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "customer_id" TEXT,
  "session_id" TEXT NOT NULL,
  "last_activity_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "guest_email" TEXT,
  "guest_email_consent_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "carts_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "carts_store_id_session_id_key" ON "carts" ("store_id", "session_id");
CREATE INDEX IF NOT EXISTS "carts_customer_id_idx" ON "carts" ("customer_id");
CREATE INDEX IF NOT EXISTS "carts_session_id_idx" ON "carts" ("session_id");
CREATE INDEX IF NOT EXISTS "carts_updated_at_idx" ON "carts" ("updated_at");
CREATE INDEX IF NOT EXISTS "carts_last_activity_at_idx" ON "carts" ("last_activity_at");

CREATE TABLE IF NOT EXISTS "catalog_import_files" (
  "id" TEXT NOT NULL,
  "job_id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "storage_key" TEXT NOT NULL,
  "mime" TEXT NOT NULL,
  "size_bytes" INTEGER NOT NULL,
  "sha256" TEXT NOT NULL,
  "original_name" TEXT NOT NULL,
  "page_count" INTEGER NOT NULL DEFAULT 1,
  "status" TEXT NOT NULL DEFAULT 'stored',
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "error_code" TEXT,
  "charged_pages" INTEGER NOT NULL DEFAULT 0,
  "items_found" INTEGER NOT NULL DEFAULT 0,
  "input_tokens" INTEGER,
  "output_tokens" INTEGER,
  "model" TEXT,
  "started_at" INTEGER,
  "finished_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "catalog_import_files_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "catalog_import_files_job_id_fkey" FOREIGN KEY ("job_id") REFERENCES "catalog_import_jobs" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "catalog_import_files_status_chk" CHECK ("status" IN ('stored','processing','done','failed','skipped_quota')),
  CONSTRAINT "catalog_import_files_pages_chk" CHECK ("page_count" >= 1 AND "page_count" <= 100),
  CONSTRAINT "catalog_import_files_charged_chk" CHECK ("charged_pages" >= 0)
);
CREATE INDEX IF NOT EXISTS "catalog_import_files_job_id_status_idx" ON "catalog_import_files" ("job_id", "status");
CREATE INDEX IF NOT EXISTS "catalog_import_files_store_id_charged_pages_started_at_idx" ON "catalog_import_files" ("store_id", "charged_pages", "started_at");

CREATE TABLE IF NOT EXISTS "catalog_import_items" (
  "id" TEXT NOT NULL,
  "job_id" TEXT NOT NULL,
  "file_id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "name" TEXT,
  "name_ar" TEXT,
  "description" TEXT,
  "description_ar" TEXT,
  "price_minor" INTEGER,
  "compare_at_minor" INTEGER,
  "price_raw" TEXT,
  "sku" TEXT,
  "category_name" TEXT,
  "category_id" TEXT,
  "tags" TEXT NOT NULL,
  "variants" TEXT NOT NULL DEFAULT '[]',
  "confidence" REAL NOT NULL DEFAULT 0,
  "flags" TEXT NOT NULL,
  "acknowledged" TEXT NOT NULL,
  "source_text" TEXT,
  "edited_fields" TEXT NOT NULL,
  "product_id" TEXT,
  "create_error_code" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "catalog_import_items_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "catalog_import_items_job_id_fkey" FOREIGN KEY ("job_id") REFERENCES "catalog_import_jobs" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "catalog_import_items_file_id_fkey" FOREIGN KEY ("file_id") REFERENCES "catalog_import_files" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "catalog_import_items_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "catalog_import_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "catalog_import_items_tags_chk" CHECK (json_valid("tags") AND json_type("tags") = 'array'),
  CONSTRAINT "catalog_import_items_variants_chk" CHECK (json_valid("variants")),
  CONSTRAINT "catalog_import_items_flags_chk" CHECK (json_valid("flags") AND json_type("flags") = 'array'),
  CONSTRAINT "catalog_import_items_acknowledged_chk" CHECK (json_valid("acknowledged") AND json_type("acknowledged") = 'array'),
  CONSTRAINT "catalog_import_items_edited_fields_chk" CHECK (json_valid("edited_fields") AND json_type("edited_fields") = 'array'),
  CONSTRAINT "catalog_import_items_status_chk" CHECK ("status" IN ('pending','accepted','rejected','created','failed')),
  CONSTRAINT "catalog_import_items_tags_max_chk" CHECK (coalesce(json_array_length("tags"), 0) <= 5),
  CONSTRAINT "catalog_import_items_variants_max_chk" CHECK (json_type("variants") = 'array' AND json_array_length("variants") <= 30),
  CONSTRAINT "catalog_import_items_price_chk" CHECK (("price_minor" IS NULL OR "price_minor" >= 0) AND ("compare_at_minor" IS NULL OR "compare_at_minor" >= 0)),
  CONSTRAINT "catalog_import_items_len_chk" CHECK (length(coalesce("name", '')) <= 300 AND length(coalesce("name_ar", '')) <= 300 AND length(coalesce("description", '')) <= 2000 AND length(coalesce("description_ar", '')) <= 2000)
);
CREATE INDEX IF NOT EXISTS "catalog_import_items_job_id_status_idx" ON "catalog_import_items" ("job_id", "status");
CREATE INDEX IF NOT EXISTS "catalog_import_items_store_id_sku_idx" ON "catalog_import_items" ("store_id", "sku");
CREATE INDEX IF NOT EXISTS "catalog_import_items_product_id_idx" ON "catalog_import_items" ("product_id");
CREATE INDEX IF NOT EXISTS "catalog_import_items_category_id_idx" ON "catalog_import_items" ("category_id");
CREATE INDEX IF NOT EXISTS "catalog_import_items_file_id_idx" ON "catalog_import_items" ("file_id");

CREATE TABLE IF NOT EXISTS "catalog_import_jobs" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "created_by" TEXT,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "error_code" TEXT,
  "files_total" INTEGER NOT NULL DEFAULT 0,
  "files_done" INTEGER NOT NULL DEFAULT 0,
  "files_failed" INTEGER NOT NULL DEFAULT 0,
  "pages_total" INTEGER NOT NULL DEFAULT 0,
  "items_total" INTEGER NOT NULL DEFAULT 0,
  "drafts_created" INTEGER NOT NULL DEFAULT 0,
  "started_at" INTEGER,
  "completed_at" INTEGER,
  "expires_at" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "catalog_import_jobs_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "catalog_import_jobs_status_chk" CHECK ("status" IN ('queued','processing','review','creating','done','failed','cancelled'))
);
CREATE INDEX IF NOT EXISTS "catalog_import_jobs_store_id_created_at_idx" ON "catalog_import_jobs" ("store_id", "created_at" DESC);
CREATE INDEX IF NOT EXISTS "catalog_import_jobs_expires_at_idx" ON "catalog_import_jobs" ("expires_at");

CREATE TABLE IF NOT EXISTS "categories" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "name_ar" TEXT,
  "slug" TEXT NOT NULL,
  "description" TEXT,
  "description_ar" TEXT,
  "image" TEXT,
  "parent_id" TEXT,
  "position" INTEGER NOT NULL DEFAULT 0,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "show_on_home_strip" INTEGER NOT NULL DEFAULT 1,
  "meta_title" TEXT,
  "meta_title_ar" TEXT,
  "meta_description" TEXT,
  "meta_description_ar" TEXT,
  "meta_description_aeo" TEXT,
  "meta_description_aeo_ar" TEXT,
  "size_chart_id" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "deleted_at" INTEGER,
  CONSTRAINT "categories_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "categories_parent_id_fkey" FOREIGN KEY ("parent_id") REFERENCES "categories" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "categories_size_chart_id_fkey" FOREIGN KEY ("size_chart_id") REFERENCES "size_charts" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "categories_is_active_chk" CHECK ("is_active" IN (0, 1)),
  CONSTRAINT "categories_show_on_home_strip_chk" CHECK ("show_on_home_strip" IN (0, 1))
);
CREATE UNIQUE INDEX IF NOT EXISTS "categories_store_id_slug_key" ON "categories" ("store_id", "slug");
CREATE INDEX IF NOT EXISTS "categories_store_id_idx" ON "categories" ("store_id");
CREATE INDEX IF NOT EXISTS "categories_parent_id_idx" ON "categories" ("parent_id");
CREATE INDEX IF NOT EXISTS "categories_is_active_idx" ON "categories" ("is_active");
CREATE INDEX IF NOT EXISTS "categories_size_chart_id_idx" ON "categories" ("size_chart_id");

CREATE TABLE IF NOT EXISTS "ci_hint_logs" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "order_id" TEXT NOT NULL,
  "feature" TEXT NOT NULL,
  "band" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "n" INTEGER NOT NULL DEFAULT 0,
  "predicted_rate" REAL,
  "outcome" TEXT,
  "outcome_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "ci_hint_logs_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ci_hint_logs_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "ci_hint_logs_band_check" CHECK ("band" IN ('typical', 'elevated', 'insufficient')),
  CONSTRAINT "ci_hint_logs_source_check" CHECK ("source" IN ('store', 'cohort', 'none')),
  CONSTRAINT "ci_hint_logs_outcome_check" CHECK ("outcome" IS NULL OR "outcome" IN ('delivered', 'returned'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "ci_hint_logs_order_id_feature_key" ON "ci_hint_logs" ("order_id", "feature");
CREATE INDEX IF NOT EXISTS "ci_hint_logs_store_id_created_at_idx" ON "ci_hint_logs" ("store_id", "created_at" DESC);
CREATE INDEX IF NOT EXISTS "ci_hint_logs_feature_outcome_created_at_idx" ON "ci_hint_logs" ("feature", "outcome", "created_at");

CREATE TABLE IF NOT EXISTS "ci_store_gates" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "feature" TEXT NOT NULL,
  "band" TEXT NOT NULL,
  "predicted_rate" REAL NOT NULL,
  "actual_rate" REAL NOT NULL,
  "resolved" INTEGER NOT NULL,
  "closed_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "ci_store_gates_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ci_store_gates_feature_check" CHECK ("feature" IN ('cod_risk', 'courier', 'fee')),
  CONSTRAINT "ci_store_gates_band_check" CHECK ("band" IN ('typical', 'elevated'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "ci_store_gates_store_id_feature_key" ON "ci_store_gates" ("store_id", "feature");

CREATE TABLE IF NOT EXISTS "cod_remittances" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "shipment_id" TEXT,
  "carrier" TEXT NOT NULL,
  "tracking_number" TEXT NOT NULL,
  "line_ref" TEXT NOT NULL,
  "batch_id" TEXT,
  "gross_amount" INTEGER NOT NULL,
  "fee_amount" INTEGER NOT NULL DEFAULT 0,
  "net_amount" INTEGER NOT NULL,
  "remitted_at" INTEGER NOT NULL,
  "source" TEXT NOT NULL DEFAULT 'csv',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "cod_remittances_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "cod_remittances_shipment_id_fkey" FOREIGN KEY ("shipment_id") REFERENCES "shipments" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "cod_remittances_net_check" CHECK ("net_amount" = "gross_amount" - "fee_amount"),
  CONSTRAINT "cod_remittances_nonneg_check" CHECK ("gross_amount" >= 0 AND "fee_amount" >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "cod_remittances_store_id_carrier_line_ref_key" ON "cod_remittances" ("store_id", "carrier", "line_ref");
CREATE INDEX IF NOT EXISTS "cod_remittances_store_id_shipment_id_idx" ON "cod_remittances" ("store_id", "shipment_id");
CREATE INDEX IF NOT EXISTS "cod_remittances_shipment_id_idx" ON "cod_remittances" ("shipment_id");
CREATE INDEX IF NOT EXISTS "cod_remittances_store_id_tracking_number_idx" ON "cod_remittances" ("store_id", "tracking_number");

-- CI-1 append-only outcome stream. The DO is the outbox: a row is written in the same transactionSync as the event it records, then shipped to Analytics Engine + R2 and stamped exported_at (the only column that may change).
CREATE TABLE IF NOT EXISTS "commerce_outcomes" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "order_id" TEXT,
  "buyer_key" TEXT,
  "area_key" TEXT,
  "carrier" TEXT,
  "payment_method" TEXT,
  "amount" INTEGER,
  "reason_code" TEXT,
  "reason_raw" TEXT,
  "source" TEXT NOT NULL DEFAULT 'store',
  "occurred_at" INTEGER NOT NULL,
  "exported_at" INTEGER,
  CONSTRAINT "commerce_outcomes_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "commerce_outcomes_kind_chk" CHECK ("kind" IN ('order_created', 'cod_confirmed', 'cod_refused', 'cod_no_reply', 'picked_up', 'delivered', 'returned', 'cancelled', 'refunded')),
  CONSTRAINT "commerce_outcomes_reason_code_chk" CHECK ("reason_code" IS NULL OR ("reason_code" IN ('refused', 'not_home', 'wrong_address', 'unreachable', 'rescheduled', 'price_or_changed_mind', 'damaged', 'other', 'unknown'))),
  CONSTRAINT "commerce_outcomes_source_chk" CHECK ("source" IN ('store', 'whatsapp'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "commerce_outcomes_store_id_order_id_kind_source_key" ON "commerce_outcomes" ("store_id", "order_id", "kind", "source");
CREATE INDEX IF NOT EXISTS "commerce_outcomes_exported_at_idx" ON "commerce_outcomes" ("exported_at");
CREATE INDEX IF NOT EXISTS "commerce_outcomes_store_id_occurred_at_idx" ON "commerce_outcomes" ("store_id", "occurred_at" DESC);

CREATE TABLE IF NOT EXISTS "count_lines" (
  "id" TEXT NOT NULL,
  "session_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "variant_id" TEXT,
  "counted_qty" INTEGER NOT NULL,
  "system_qty" INTEGER NOT NULL,
  "variance" INTEGER NOT NULL,
  "scanned_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "count_lines_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "count_lines_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "count_sessions" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "count_lines_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "count_lines_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "count_lines_session_id_product_id_variant_id_key" ON "count_lines" ("session_id", "product_id", "variant_id");
CREATE INDEX IF NOT EXISTS "count_lines_session_id_idx" ON "count_lines" ("session_id");
CREATE INDEX IF NOT EXISTS "count_lines_product_id_idx" ON "count_lines" ("product_id");
CREATE INDEX IF NOT EXISTS "count_lines_variant_id_idx" ON "count_lines" ("variant_id");

CREATE TABLE IF NOT EXISTS "count_sessions" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'open',
  "note" TEXT,
  "created_by" TEXT,
  "closed_at" INTEGER,
  "reconciled_at" INTEGER,
  "adjustment_id" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "count_sessions_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "count_sessions_status_chk" CHECK ("status" IN ('open', 'closed', 'reconciled'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "count_sessions_adjustment_id_key" ON "count_sessions" ("adjustment_id");
CREATE INDEX IF NOT EXISTS "count_sessions_store_id_status_idx" ON "count_sessions" ("store_id", "status");
CREATE INDEX IF NOT EXISTS "count_sessions_store_id_created_at_idx" ON "count_sessions" ("store_id", "created_at" DESC);

CREATE TABLE IF NOT EXISTS "coupons" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "name_ar" TEXT,
  "description" TEXT,
  "description_ar" TEXT,
  "type" TEXT NOT NULL DEFAULT 'percentage',
  "value" INTEGER NOT NULL,
  "min_order_amount" INTEGER,
  "max_discount" INTEGER,
  "usage_limit" INTEGER,
  "usage_count" INTEGER NOT NULL DEFAULT 0,
  "usage_limit_per_user" INTEGER,
  "customer_group_id" TEXT,
  "first_order_only" INTEGER NOT NULL DEFAULT 0,
  "min_quantity" INTEGER,
  "scope_product_ids" TEXT NOT NULL,
  "scope_category_ids" TEXT NOT NULL,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "starts_at" INTEGER,
  "expires_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "coupons_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "coupons_customer_group_id_fkey" FOREIGN KEY ("customer_group_id") REFERENCES "customer_groups" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "coupons_type_chk" CHECK ("type" IN ('percentage', 'fixed', 'free_shipping')),
  CONSTRAINT "coupons_first_order_only_chk" CHECK ("first_order_only" IN (0, 1)),
  CONSTRAINT "coupons_scope_product_ids_chk" CHECK (json_valid("scope_product_ids") AND json_type("scope_product_ids") = 'array'),
  CONSTRAINT "coupons_scope_category_ids_chk" CHECK (json_valid("scope_category_ids") AND json_type("scope_category_ids") = 'array'),
  CONSTRAINT "coupons_is_active_chk" CHECK ("is_active" IN (0, 1))
);
CREATE UNIQUE INDEX IF NOT EXISTS "coupons_store_id_code_key" ON "coupons" ("store_id", "code");
CREATE INDEX IF NOT EXISTS "coupons_code_idx" ON "coupons" ("code");
CREATE INDEX IF NOT EXISTS "coupons_is_active_idx" ON "coupons" ("is_active");
CREATE INDEX IF NOT EXISTS "coupons_store_id_customer_group_id_idx" ON "coupons" ("store_id", "customer_group_id");
CREATE INDEX IF NOT EXISTS "coupons_customer_group_id_idx" ON "coupons" ("customer_group_id");

CREATE TABLE IF NOT EXISTS "customer_addresses" (
  "id" TEXT NOT NULL,
  "customer_id" TEXT NOT NULL,
  "label" TEXT,
  "street" TEXT NOT NULL,
  "block" TEXT,
  "area" TEXT NOT NULL,
  "governorate" TEXT,
  "building_number" TEXT,
  "notes" TEXT,
  "is_default" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "customer_addresses_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "customer_addresses_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "customer_addresses_is_default_chk" CHECK ("is_default" IN (0, 1))
);
CREATE INDEX IF NOT EXISTS "customer_addresses_customer_id_idx" ON "customer_addresses" ("customer_id");

CREATE TABLE IF NOT EXISTS "customer_cohort_snapshots" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "cohort_month" TEXT NOT NULL,
  "period_offset" INTEGER NOT NULL,
  "customers_total" INTEGER NOT NULL,
  "customers_active" INTEGER NOT NULL,
  "orders_in_period" INTEGER NOT NULL,
  "revenue_in_period" INTEGER NOT NULL,
  "computed_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "customer_cohort_snapshots_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "customer_cohort_snapshots_store_id_cohort_month_period_offset_key" ON "customer_cohort_snapshots" ("store_id", "cohort_month", "period_offset");
CREATE INDEX IF NOT EXISTS "customer_cohort_snapshots_store_id_cohort_month_idx" ON "customer_cohort_snapshots" ("store_id", "cohort_month");

CREATE TABLE IF NOT EXISTS "customer_groups" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "name_ar" TEXT,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "is_default" INTEGER NOT NULL DEFAULT 0,
  "pricing_mode" TEXT NOT NULL DEFAULT 'none',
  "discount_bps" INTEGER NOT NULL DEFAULT 0,
  "requires_approval" INTEGER NOT NULL DEFAULT 0,
  "is_wholesale" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "customer_groups_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "customer_groups_is_active_chk" CHECK ("is_active" IN (0, 1)),
  CONSTRAINT "customer_groups_is_default_chk" CHECK ("is_default" IN (0, 1)),
  CONSTRAINT "customer_groups_requires_approval_chk" CHECK ("requires_approval" IN (0, 1)),
  CONSTRAINT "customer_groups_is_wholesale_chk" CHECK ("is_wholesale" IN (0, 1)),
  CONSTRAINT "customer_groups_pricing_mode_chk" CHECK ("pricing_mode" IN ('none', 'percent_off')),
  CONSTRAINT "customer_groups_discount_bps_chk" CHECK ("discount_bps" BETWEEN 0 AND 9000)
);
CREATE UNIQUE INDEX IF NOT EXISTS "customer_groups_store_id_name_key" ON "customer_groups" ("store_id", "name");
CREATE INDEX IF NOT EXISTS "customer_groups_store_id_is_active_idx" ON "customer_groups" ("store_id", "is_active");
CREATE UNIQUE INDEX IF NOT EXISTS "customer_groups_one_default_per_store" ON "customer_groups" ("store_id") WHERE "is_default" = 1;

CREATE TABLE IF NOT EXISTS "customer_rfm_snapshots" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "customer_id" TEXT NOT NULL,
  "is_guest" INTEGER NOT NULL DEFAULT 0,
  "recency_days" INTEGER NOT NULL,
  "frequency_orders" INTEGER NOT NULL,
  "monetary_fils" INTEGER NOT NULL,
  "rfm_score" INTEGER NOT NULL,
  "segment" TEXT NOT NULL,
  "previous_segment" TEXT,
  "computed_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "customer_rfm_snapshots_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "customer_rfm_snapshots_is_guest_chk" CHECK ("is_guest" IN (0, 1)),
  CONSTRAINT "customer_rfm_snapshots_segment_chk" CHECK ("segment" IN ('vip', 'loyal', 'potential', 'new_customer', 'at_risk', 'hibernating', 'lost')),
  CONSTRAINT "customer_rfm_snapshots_previous_segment_chk" CHECK ("previous_segment" IS NULL OR ("previous_segment" IN ('vip', 'loyal', 'potential', 'new_customer', 'at_risk', 'hibernating', 'lost')))
);
CREATE UNIQUE INDEX IF NOT EXISTS "customer_rfm_snapshots_store_id_customer_id_key" ON "customer_rfm_snapshots" ("store_id", "customer_id");
CREATE INDEX IF NOT EXISTS "customer_rfm_snapshots_store_id_segment_idx" ON "customer_rfm_snapshots" ("store_id", "segment");
CREATE INDEX IF NOT EXISTS "customer_rfm_snapshots_store_id_rfm_score_idx" ON "customer_rfm_snapshots" ("store_id", "rfm_score" DESC);

CREATE TABLE IF NOT EXISTS "customer_wallets" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "customer_id" TEXT NOT NULL,
  "balance" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "customer_wallets_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "customer_wallets_balance_non_negative" CHECK ("balance" >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "customer_wallets_store_id_customer_id_key" ON "customer_wallets" ("store_id", "customer_id");
CREATE INDEX IF NOT EXISTS "customer_wallets_store_id_balance_idx" ON "customer_wallets" ("store_id", "balance");
CREATE INDEX IF NOT EXISTS "customer_wallets_customer_id_idx" ON "customer_wallets" ("customer_id");

CREATE TABLE IF NOT EXISTS "customers" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "email" TEXT,
  "first_name" TEXT NOT NULL,
  "last_name" TEXT NOT NULL,
  "phone" TEXT,
  "notes" TEXT,
  "total_orders" INTEGER NOT NULL DEFAULT 0,
  "total_spent" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "preferred_locale" TEXT,
  "last_locale_choice" INTEGER,
  "group_id" TEXT,
  "user_id" TEXT,
  "buyer_key" TEXT,
  CONSTRAINT "customers_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "customers_group_id_fkey" FOREIGN KEY ("group_id") REFERENCES "customer_groups" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "customers_store_id_email_key" ON "customers" ("store_id", "email");
CREATE UNIQUE INDEX IF NOT EXISTS "customers_store_id_phone_key" ON "customers" ("store_id", "phone");
CREATE INDEX IF NOT EXISTS "customers_store_id_idx" ON "customers" ("store_id");
CREATE INDEX IF NOT EXISTS "customers_email_idx" ON "customers" ("email");
CREATE INDEX IF NOT EXISTS "customers_created_at_idx" ON "customers" ("created_at");
CREATE INDEX IF NOT EXISTS "customers_store_id_group_id_idx" ON "customers" ("store_id", "group_id");
CREATE INDEX IF NOT EXISTS "customers_group_id_idx" ON "customers" ("group_id");
CREATE INDEX IF NOT EXISTS "customers_buyer_key_idx" ON "customers" ("buyer_key");
CREATE UNIQUE INDEX IF NOT EXISTS "customers_store_id_user_id_key" ON "customers" ("store_id", "user_id") WHERE "user_id" IS NOT NULL;

-- Write-through outbox to D1 (Task 1.4 + entity index): rows are retried by the DO alarm until the D1 write is acknowledged.
CREATE TABLE IF NOT EXISTS "d1_outbox" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "kind" TEXT NOT NULL,
  "payload" TEXT NOT NULL,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "next_attempt_at" INTEGER NOT NULL,
  "done_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "d1_outbox_kind_chk" CHECK ("kind" IN ('directory_update', 'entity_index')),
  CONSTRAINT "d1_outbox_payload_chk" CHECK (json_valid("payload"))
);
CREATE INDEX IF NOT EXISTS "d1_outbox_done_at_next_attempt_at_idx" ON "d1_outbox" ("done_at", "next_attempt_at");

CREATE TABLE IF NOT EXISTS "deadstock_flags" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "variant_id" TEXT,
  "days_since_sale" INTEGER NOT NULL,
  "stock_on_hand" INTEGER NOT NULL,
  "stock_value_fils" INTEGER,
  "suggested_discount_bps" INTEGER NOT NULL,
  "clearance_copy_en" TEXT NOT NULL,
  "clearance_copy_ar" TEXT,
  "status" TEXT NOT NULL DEFAULT 'open',
  "coupon_code" TEXT,
  "dismissed_by" TEXT,
  "dismissed_at" INTEGER,
  "scanned_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "deadstock_flags_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "deadstock_flags_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "deadstock_flags_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "deadstock_flags_status_chk" CHECK ("status" IN ('open', 'accepted_clearance', 'dismissed', 'expired'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "deadstock_flags_store_id_product_id_variant_id_scanned_at_key" ON "deadstock_flags" ("store_id", "product_id", "variant_id", "scanned_at");
CREATE INDEX IF NOT EXISTS "deadstock_flags_store_id_status_idx" ON "deadstock_flags" ("store_id", "status");
CREATE INDEX IF NOT EXISTS "deadstock_flags_product_id_idx" ON "deadstock_flags" ("product_id");
CREATE INDEX IF NOT EXISTS "deadstock_flags_variant_id_idx" ON "deadstock_flags" ("variant_id");

-- Per-DO transaction flags that replace Postgres GUCs read by triggers (app.gold_reprice). Set and cleared inside one transactionSync by the repricer only.
CREATE TABLE IF NOT EXISTS "do_flags" (
  "name" TEXT NOT NULL,
  "value" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "do_flags_pkey" PRIMARY KEY ("name")
);

CREATE TABLE IF NOT EXISTS "eta_connections" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "enabled" INTEGER NOT NULL DEFAULT 0,
  "environment" TEXT NOT NULL DEFAULT 'preprod',
  "credentials_enc" TEXT NOT NULL,
  "pos_serial" TEXT NOT NULL,
  "branch_code" TEXT NOT NULL,
  "activity_code" TEXT NOT NULL,
  "default_item_code" TEXT NOT NULL,
  "address" TEXT NOT NULL,
  "signing_bridge_url" TEXT,
  "last_check_status" TEXT,
  "last_checked_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "eta_connections_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "eta_connections_enabled_chk" CHECK ("enabled" IN (0, 1)),
  CONSTRAINT "eta_connections_address_chk" CHECK (json_valid("address")),
  CONSTRAINT "eta_connections_environment_check" CHECK ("environment" IN ('preprod', 'prod'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "eta_connections_store_id_key" ON "eta_connections" ("store_id");

CREATE TABLE IF NOT EXISTS "eta_receipts" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "order_id" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "seq" INTEGER NOT NULL DEFAULT 1,
  "refund_key" TEXT,
  "line_map" TEXT,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "environment" TEXT NOT NULL,
  "receipt_number" TEXT,
  "uuid" TEXT,
  "previous_uuid" TEXT,
  "document" TEXT,
  "total_piastres" INTEGER,
  "issued_at" INTEGER,
  "deadline_at" INTEGER,
  "submission_uuid" TEXT,
  "long_id" TEXT,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "next_attempt_at" INTEGER,
  "error_code" TEXT,
  "error_message" TEXT,
  "accepted_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "eta_receipts_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "eta_receipts_line_map_chk" CHECK ("line_map" IS NULL OR (json_valid("line_map"))),
  CONSTRAINT "eta_receipts_document_chk" CHECK ("document" IS NULL OR (json_valid("document"))),
  CONSTRAINT "eta_receipts_kind_check" CHECK ("kind" IN ('sale', 'return')),
  CONSTRAINT "eta_receipts_status_check" CHECK ("status" IN ('queued', 'retrying', 'submitted', 'accepted', 'rejected', 'failed', 'late', 'manual')),
  CONSTRAINT "eta_receipts_environment_check" CHECK ("environment" IN ('preprod', 'prod'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "eta_receipts_store_id_order_id_kind_seq_key" ON "eta_receipts" ("store_id", "order_id", "kind", "seq");
CREATE INDEX IF NOT EXISTS "eta_receipts_store_id_status_next_attempt_at_idx" ON "eta_receipts" ("store_id", "status", "next_attempt_at");
CREATE INDEX IF NOT EXISTS "eta_receipts_store_id_order_id_idx" ON "eta_receipts" ("store_id", "order_id");
CREATE INDEX IF NOT EXISTS "eta_receipts_store_id_order_id_refund_key_idx" ON "eta_receipts" ("store_id", "order_id", "refund_key");
CREATE INDEX IF NOT EXISTS "eta_receipts_status_next_attempt_at_idx" ON "eta_receipts" ("status", "next_attempt_at");

CREATE TABLE IF NOT EXISTS "expenses" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "expense_number" TEXT NOT NULL,
  "supplier_id" TEXT,
  "expense_account_id" TEXT NOT NULL,
  "paid_from_account_id" TEXT NOT NULL,
  "amount" INTEGER NOT NULL,
  "tax_amount" INTEGER NOT NULL DEFAULT 0,
  "total" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "fx_rate" INTEGER DEFAULT 100000000,
  "original_amount" INTEGER DEFAULT 0,
  "expense_date" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'draft',
  "receipt_image_url" TEXT,
  "ocr_json" TEXT,
  "category_ai_confidence" REAL,
  "ocr_model_version" TEXT,
  "ocr_processed_at" INTEGER,
  "approved_by" TEXT,
  "approved_at" INTEGER,
  "journal_entry_id" TEXT,
  "posted_at" INTEGER,
  "notes" TEXT,
  "notes_ar" TEXT,
  "created_by" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "expenses_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "expenses_supplier_id_fkey" FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "expenses_expense_account_id_fkey" FOREIGN KEY ("expense_account_id") REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "expenses_paid_from_account_id_fkey" FOREIGN KEY ("paid_from_account_id") REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "expenses_status_chk" CHECK ("status" IN ('draft', 'pending', 'approved', 'posted', 'rejected')),
  CONSTRAINT "expenses_ocr_json_chk" CHECK ("ocr_json" IS NULL OR (json_valid("ocr_json"))),
  CONSTRAINT "expenses_total_matches_amount_plus_tax" CHECK (total = amount + tax_amount),
  CONSTRAINT "expenses_amount_nonneg" CHECK (amount >= 0 AND tax_amount >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "expenses_journal_entry_id_key" ON "expenses" ("journal_entry_id");
CREATE UNIQUE INDEX IF NOT EXISTS "expenses_store_id_expense_number_key" ON "expenses" ("store_id", "expense_number");
CREATE INDEX IF NOT EXISTS "expenses_store_id_status_idx" ON "expenses" ("store_id", "status");
CREATE INDEX IF NOT EXISTS "expenses_store_id_expense_date_idx" ON "expenses" ("store_id", "expense_date" DESC);
CREATE INDEX IF NOT EXISTS "expenses_paid_from_account_id_idx" ON "expenses" ("paid_from_account_id");
CREATE INDEX IF NOT EXISTS "expenses_expense_account_id_idx" ON "expenses" ("expense_account_id");
CREATE INDEX IF NOT EXISTS "expenses_supplier_id_idx" ON "expenses" ("supplier_id");

CREATE TABLE IF NOT EXISTS "fiscal_document_counters" (
  "store_id" TEXT NOT NULL,
  "doc_type" TEXT NOT NULL,
  "last_serial" INTEGER NOT NULL DEFAULT 0,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "fiscal_document_counters_pkey" PRIMARY KEY ("store_id", "doc_type"),
  CONSTRAINT "fiscal_document_counters_doc_type_chk" CHECK ("doc_type" IN ('tax_invoice', 'receipt', 'credit_note', 'refund_receipt', 'order_record', 'billing_record')),
  CONSTRAINT "fiscal_document_counters_last_serial_check" CHECK ("last_serial" >= 0)
);

CREATE TABLE IF NOT EXISTS "fiscal_documents" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "order_id" TEXT,
  "doc_type" TEXT NOT NULL,
  "serial" INTEGER,
  "number" TEXT,
  "status" TEXT NOT NULL DEFAULT 'issued',
  "issued_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "cancelled_at" INTEGER,
  "original_document_id" TEXT,
  "original_number" TEXT,
  "original_issued_at" INTEGER,
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "net_amount" INTEGER NOT NULL,
  "vat_amount" INTEGER NOT NULL DEFAULT 0,
  "total_amount" INTEGER NOT NULL,
  "vat_rate_bps" INTEGER,
  "seller_trn" TEXT,
  "payload" TEXT NOT NULL,
  "refund_ref" TEXT,
  "eta_uuid" TEXT,
  "eta_submission_id" TEXT,
  "eta_status" TEXT,
  "eta_submitted_at" INTEGER,
  "retain_until" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "fiscal_documents_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "fiscal_documents_doc_type_chk" CHECK ("doc_type" IN ('tax_invoice', 'receipt', 'credit_note', 'refund_receipt', 'order_record', 'billing_record')),
  CONSTRAINT "fiscal_documents_payload_chk" CHECK (json_valid("payload")),
  CONSTRAINT "fiscal_documents_status_check" CHECK ("status" IN ('issued', 'cancelled')),
  CONSTRAINT "fiscal_documents_serial_check" CHECK (("doc_type" IN ('order_record', 'billing_record') AND "serial" IS NULL AND "number" IS NULL) OR ("doc_type" NOT IN ('order_record', 'billing_record') AND "serial" >= 1 AND "number" IS NOT NULL)),
  CONSTRAINT "fiscal_documents_original_check" CHECK ("doc_type" NOT IN ('credit_note', 'refund_receipt') OR ("original_number" IS NOT NULL AND "original_issued_at" IS NOT NULL)),
  CONSTRAINT "fiscal_documents_amounts_check" CHECK ("vat_amount" >= 0 AND "net_amount" >= 0 AND "total_amount" >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "fiscal_documents_store_id_doc_type_serial_key" ON "fiscal_documents" ("store_id", "doc_type", "serial");
CREATE UNIQUE INDEX IF NOT EXISTS "fiscal_documents_store_id_refund_ref_key" ON "fiscal_documents" ("store_id", "refund_ref");
CREATE INDEX IF NOT EXISTS "fiscal_documents_store_id_order_id_idx" ON "fiscal_documents" ("store_id", "order_id");
CREATE INDEX IF NOT EXISTS "fiscal_documents_store_id_issued_at_idx" ON "fiscal_documents" ("store_id", "issued_at" DESC);

CREATE TABLE IF NOT EXISTS "frequently_bought_together" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "product_id_1" TEXT NOT NULL,
  "product_id_2" TEXT NOT NULL,
  "co_occurrence_count" INTEGER NOT NULL DEFAULT 0,
  "last_calculated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "frequently_bought_together_pkey" PRIMARY KEY ("id"),
