CREATE INDEX IF NOT EXISTS "journal_entries_store_id_posted_at_idx" ON "journal_entries" ("store_id", "posted_at" DESC);
CREATE INDEX IF NOT EXISTS "journal_entries_source_source_id_idx" ON "journal_entries" ("source", "source_id");
CREATE INDEX IF NOT EXISTS "journal_entries_store_id_status_idx" ON "journal_entries" ("store_id", "status");
CREATE UNIQUE INDEX IF NOT EXISTS "journal_entries_store_source_source_id_unique" ON "journal_entries" (store_id, source, source_id) WHERE source_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS "journal_lines" (
  "id" TEXT NOT NULL,
  "entry_id" TEXT NOT NULL,
  "account_id" TEXT NOT NULL,
  "debit" INTEGER NOT NULL DEFAULT 0,
  "credit" INTEGER NOT NULL DEFAULT 0,
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "fx_rate" INTEGER DEFAULT 100000000,
  "original_amount" INTEGER DEFAULT 0,
  "line_memo" TEXT,
  "line_memo_ar" TEXT,
  "ref_table" TEXT,
  "ref_id" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "journal_lines_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "journal_lines_entry_id_fkey" FOREIGN KEY ("entry_id") REFERENCES "journal_entries" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "journal_lines_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "journal_lines_debit_credit_nonneg" CHECK (debit >= 0 AND credit >= 0),
  CONSTRAINT "journal_lines_debit_xor_credit" CHECK ((debit = 0 AND credit > 0) OR (debit > 0 AND credit = 0))
);
CREATE INDEX IF NOT EXISTS "journal_lines_entry_id_idx" ON "journal_lines" ("entry_id");
CREATE INDEX IF NOT EXISTS "journal_lines_account_id_idx" ON "journal_lines" ("account_id");
CREATE INDEX IF NOT EXISTS "journal_lines_ref_table_ref_id_idx" ON "journal_lines" ("ref_table", "ref_id");

