  "variant_id" TEXT,
  "product_name" TEXT NOT NULL,
  "variant_name" TEXT,
  "variant_name_ar" TEXT,
  "personalisation" TEXT,
  "sku" TEXT,
  "quantity" INTEGER NOT NULL,
  "price" INTEGER NOT NULL,
  "cost_price" INTEGER,
  "total" INTEGER NOT NULL,
  "cost_price_deferred" INTEGER NOT NULL DEFAULT 0,
  "list_price" INTEGER,
  "price_source" TEXT,
  "price_tier_min_qty" INTEGER,
  "price_group_applied" INTEGER,
  "tier_ladder" TEXT,
  "gold_snapshot" TEXT,
  "picked_qty" INTEGER NOT NULL DEFAULT 0,
  "picked_at" INTEGER,
  "bundle_id" TEXT,
  "bundle_group_id" TEXT,
  "bundle_name" TEXT,
  "bundle_name_ar" TEXT,
  CONSTRAINT "order_items_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "order_items_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "order_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "order_items_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "order_items_cost_price_deferred_chk" CHECK ("cost_price_deferred" IN (0, 1)),
  CONSTRAINT "order_items_price_group_applied_chk" CHECK ("price_group_applied" IS NULL OR ("price_group_applied" IN (0, 1))),
  CONSTRAINT "order_items_tier_ladder_chk" CHECK ("tier_ladder" IS NULL OR (json_valid("tier_ladder"))),
  CONSTRAINT "order_items_gold_snapshot_chk" CHECK ("gold_snapshot" IS NULL OR (json_valid("gold_snapshot"))),
  CONSTRAINT "order_items_price_source_chk" CHECK ("price_source" IS NULL OR "price_source" IN ('base', 'tier', 'group')),
  CONSTRAINT "order_items_gold_snapshot_check" CHECK ("gold_snapshot" IS NULL OR json_type("gold_snapshot") = 'object')
);
CREATE INDEX IF NOT EXISTS "order_items_order_id_idx" ON "order_items" ("order_id");
CREATE INDEX IF NOT EXISTS "order_items_product_id_idx" ON "order_items" ("product_id");
CREATE INDEX IF NOT EXISTS "order_items_variant_id_idx" ON "order_items" ("variant_id");
CREATE INDEX IF NOT EXISTS "order_items_bundle_group_id_idx" ON "order_items" ("bundle_group_id");

CREATE TABLE IF NOT EXISTS "orders" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "customer_id" TEXT,
  "order_number" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "payment_status" TEXT NOT NULL DEFAULT 'unpaid',
  "subtotal" INTEGER NOT NULL,
  "tax" INTEGER NOT NULL DEFAULT 0,
  "tax_included_in_price" INTEGER NOT NULL DEFAULT 0,
  "price_group_name" TEXT,
  "seller_tax_registration_number" TEXT,
  "seller_tax_legal_name" TEXT,
  "tax_rate_bps" INTEGER,
  "shipping" INTEGER NOT NULL DEFAULT 0,
  "discount" INTEGER NOT NULL DEFAULT 0,
  "cod_fee" INTEGER NOT NULL DEFAULT 0,
  "taxable_amount" INTEGER,
  "total" INTEGER NOT NULL,
  "extra_amount" INTEGER NOT NULL DEFAULT 0,
  "extra_amount_note" TEXT,
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "coupon_code" TEXT,
  "coupon_discount" INTEGER NOT NULL DEFAULT 0,
  "promotion_discount" INTEGER NOT NULL DEFAULT 0,
  "applied_promotion_id" TEXT,
  "bundle_discount" INTEGER NOT NULL DEFAULT 0,
  "loyalty_points_redeemed" INTEGER,
  "loyalty_discount" INTEGER NOT NULL DEFAULT 0,
  "wallet_amount" INTEGER NOT NULL DEFAULT 0,
  "notes" TEXT,
  "customer_notes" TEXT,
  "shipping_address" TEXT NOT NULL,
  "billing_address" TEXT NOT NULL,
  "area_key" TEXT,
  "buyer_key" TEXT,
  "shipped_at" INTEGER,
  "delivered_at" INTEGER,
  "review_request_sent_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "deleted_at" INTEGER,
  "locale" TEXT,
  "sms_opt_in" INTEGER NOT NULL DEFAULT 0,
  "payment_confirmation_expires_at" INTEGER,
  "idempotency_key" TEXT,
  "webhook_processed_at" INTEGER,
  "checkout_idempotency_key" TEXT,
  "checkout_request_hash" TEXT,
  "stuck_payment_alerted_at" INTEGER,
  "order_created_notified_at" INTEGER,
  "refund_reversed_at" INTEGER,
  "refund_reversal_requested_at" INTEGER,
  "status_fanout_requested_at" INTEGER,
  "status_fanout_claimed_at" INTEGER,
  "status_fanout_requested_status" TEXT,
  "status_fanout_completed_at" INTEGER,
  "payment_gateway_abandoned_at" INTEGER,
  "source" TEXT DEFAULT 'web',
  "checkout_ip" TEXT,
  "manual_hold_admitted" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "orders_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "orders_applied_promotion_id_fkey" FOREIGN KEY ("applied_promotion_id") REFERENCES "promotions" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "orders_status_chk" CHECK ("status" IN ('pending', 'awaiting_payment_confirmation', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled', 'refunded')),
  CONSTRAINT "orders_payment_status_chk" CHECK ("payment_status" IN ('unpaid', 'paid', 'failed', 'refunded', 'disputed')),
  CONSTRAINT "orders_tax_included_in_price_chk" CHECK ("tax_included_in_price" IN (0, 1)),
  CONSTRAINT "orders_shipping_address_chk" CHECK (json_valid("shipping_address")),
  CONSTRAINT "orders_billing_address_chk" CHECK (json_valid("billing_address")),
  CONSTRAINT "orders_sms_opt_in_chk" CHECK ("sms_opt_in" IN (0, 1)),
  CONSTRAINT "orders_manual_hold_admitted_chk" CHECK ("manual_hold_admitted" IN (0, 1)),
  CONSTRAINT "orders_wallet_amount_non_negative" CHECK ("wallet_amount" >= 0),
  CONSTRAINT "orders_cod_fee_nonneg" CHECK ("cod_fee" >= 0),
  CONSTRAINT "orders_buyer_key_check" CHECK ("buyer_key" IS NULL OR (length("buyer_key") = 64 AND "buyer_key" NOT GLOB '*[^0-9a-f]*'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "orders_order_number_key" ON "orders" ("order_number");
CREATE UNIQUE INDEX IF NOT EXISTS "orders_idempotency_key_key" ON "orders" ("idempotency_key");
CREATE UNIQUE INDEX IF NOT EXISTS "orders_store_id_checkout_idempotency_key_key" ON "orders" ("store_id", "checkout_idempotency_key");
CREATE INDEX IF NOT EXISTS "orders_customer_id_idx" ON "orders" ("customer_id");
CREATE INDEX IF NOT EXISTS "orders_status_idx" ON "orders" ("status");
CREATE INDEX IF NOT EXISTS "orders_payment_status_idx" ON "orders" ("payment_status");
CREATE INDEX IF NOT EXISTS "orders_created_at_idx" ON "orders" ("created_at");
CREATE INDEX IF NOT EXISTS "orders_store_id_customer_id_idx" ON "orders" ("store_id", "customer_id");
CREATE INDEX IF NOT EXISTS "orders_store_id_status_idx" ON "orders" ("store_id", "status");
CREATE INDEX IF NOT EXISTS "orders_store_id_created_at_idx" ON "orders" ("store_id", "created_at" DESC);
CREATE INDEX IF NOT EXISTS "orders_store_id_payment_gateway_abandoned_at_idx" ON "orders" ("store_id", "payment_gateway_abandoned_at");
CREATE INDEX IF NOT EXISTS "orders_payment_confirmation_expires_at_idx" ON "orders" ("payment_confirmation_expires_at");
CREATE INDEX IF NOT EXISTS "orders_applied_promotion_id_idx" ON "orders" ("applied_promotion_id");
CREATE INDEX IF NOT EXISTS "orders_payment_gateway_abandoned_at_idx" ON "orders" ("store_id", "payment_gateway_abandoned_at") WHERE "payment_gateway_abandoned_at" IS NOT NULL;
CREATE INDEX IF NOT EXISTS "orders_refund_reversal_pending_idx" ON "orders" ("updated_at") WHERE "refund_reversed_at" IS NULL AND "status" IN ('cancelled', 'refunded');
CREATE INDEX IF NOT EXISTS "orders_refund_reversal_requested_idx" ON "orders" ("refund_reversal_requested_at") WHERE "refund_reversed_at" IS NULL AND "refund_reversal_requested_at" IS NOT NULL;
CREATE INDEX IF NOT EXISTS "orders_status_fanout_pending_idx" ON "orders" ("status_fanout_requested_at") WHERE "status_fanout_claimed_at" IS NULL AND "status_fanout_requested_at" IS NOT NULL;
CREATE INDEX IF NOT EXISTS "orders_open_hold_phone_idx" ON "orders" ("store_id", (json_extract(shipping_address, '$.phone'))) WHERE "status" IN ('pending', 'awaiting_payment_confirmation') AND "payment_status" = 'unpaid' AND "deleted_at" IS NULL;
CREATE INDEX IF NOT EXISTS "orders_open_hold_email_idx" ON "orders" ("store_id", (lower(trim(json_extract(shipping_address, '$.email'))))) WHERE "status" IN ('pending', 'awaiting_payment_confirmation') AND "payment_status" = 'unpaid' AND "deleted_at" IS NULL;
CREATE INDEX IF NOT EXISTS "orders_open_hold_ip_idx" ON "orders" ("store_id", "checkout_ip") WHERE "status" IN ('pending', 'awaiting_payment_confirmation') AND "payment_status" = 'unpaid' AND "deleted_at" IS NULL;
CREATE INDEX IF NOT EXISTS "orders_store_buyer_key_created_idx" ON "orders" ("store_id", "buyer_key", "created_at") WHERE "buyer_key" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "payment_configs" (
  "id" TEXT NOT NULL,
  "store_id" TEXT,
  "provider" TEXT NOT NULL,
  "is_enabled" INTEGER NOT NULL DEFAULT 0,
  "is_default" INTEGER NOT NULL DEFAULT 0,
  "display_name" TEXT,
  "display_name_ar" TEXT,
  "api_key" TEXT,
  "secret_key" TEXT,
  "merchant_id" TEXT,
  "webhook_secret" TEXT,
  "api_key_last4" TEXT,
  "merchant_id_last4" TEXT,
  "credentials" TEXT,
  "credential_hints" TEXT NOT NULL DEFAULT '{}',
  "connection_test" TEXT,
  "test_mode" INTEGER NOT NULL DEFAULT 1,
  "supported_methods" TEXT NOT NULL DEFAULT '[]',
  "supported_currencies" TEXT NOT NULL DEFAULT '["EGP"]',
  "settings" TEXT NOT NULL DEFAULT '{}',
  "fixed_fee" INTEGER NOT NULL DEFAULT 0,
  "percentage_fee" INTEGER NOT NULL DEFAULT 0,
  "last_health_check" INTEGER,
  "health_status" TEXT NOT NULL DEFAULT 'unknown',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "created_by" TEXT,
  "updated_by" TEXT,
  CONSTRAINT "payment_configs_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "payment_configs_is_enabled_chk" CHECK ("is_enabled" IN (0, 1)),
  CONSTRAINT "payment_configs_is_default_chk" CHECK ("is_default" IN (0, 1)),
  CONSTRAINT "payment_configs_credential_hints_chk" CHECK (json_valid("credential_hints")),
  CONSTRAINT "payment_configs_connection_test_chk" CHECK ("connection_test" IS NULL OR (json_valid("connection_test"))),
  CONSTRAINT "payment_configs_test_mode_chk" CHECK ("test_mode" IN (0, 1)),
  CONSTRAINT "payment_configs_supported_methods_chk" CHECK (json_valid("supported_methods") AND json_type("supported_methods") = 'array'),
  CONSTRAINT "payment_configs_supported_currencies_chk" CHECK (json_valid("supported_currencies") AND json_type("supported_currencies") = 'array'),
  CONSTRAINT "payment_configs_settings_chk" CHECK (json_valid("settings")),
  CONSTRAINT "payment_configs_health_status_chk" CHECK ("health_status" IN ('healthy', 'degraded', 'down', 'unknown')),
  CONSTRAINT "payment_configs_provider_code_check" CHECK ((length("provider") BETWEEN 2 AND 32 AND "provider" GLOB '[a-z]*' AND "provider" NOT GLOB '*[^a-z0-9_]*'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "payment_configs_store_id_provider_key" ON "payment_configs" ("store_id", "provider");
CREATE INDEX IF NOT EXISTS "payment_configs_store_id_idx" ON "payment_configs" ("store_id");
CREATE INDEX IF NOT EXISTS "payment_configs_provider_idx" ON "payment_configs" ("provider");
CREATE INDEX IF NOT EXISTS "payment_configs_is_enabled_idx" ON "payment_configs" ("is_enabled");

CREATE TABLE IF NOT EXISTS "payment_events" (
  "id" TEXT NOT NULL,
  "payment_id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "order_id" TEXT NOT NULL,
  "event_type" TEXT NOT NULL,
  "from_status" TEXT,
  "to_status" TEXT,
  "provider" TEXT,
  "provider_payload" TEXT,
  "details" TEXT NOT NULL DEFAULT '{}',
  "triggered_by_user_id" TEXT,
  "occurred_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "payment_events_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "payment_events_payment_id_fkey" FOREIGN KEY ("payment_id") REFERENCES "payments" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "payment_events_from_status_chk" CHECK ("from_status" IS NULL OR ("from_status" IN ('pending', 'processing', 'completed', 'failed', 'cancelled', 'expired', 'refunded', 'partially_refunded', 'disputed', 'cod_pending'))),
  CONSTRAINT "payment_events_to_status_chk" CHECK ("to_status" IS NULL OR ("to_status" IN ('pending', 'processing', 'completed', 'failed', 'cancelled', 'expired', 'refunded', 'partially_refunded', 'disputed', 'cod_pending'))),
  CONSTRAINT "payment_events_provider_payload_chk" CHECK ("provider_payload" IS NULL OR (json_valid("provider_payload"))),
  CONSTRAINT "payment_events_details_chk" CHECK (json_valid("details"))
);
CREATE INDEX IF NOT EXISTS "payment_events_payment_id_occurred_at_idx" ON "payment_events" ("payment_id", "occurred_at");
CREATE INDEX IF NOT EXISTS "payment_events_store_id_occurred_at_idx" ON "payment_events" ("store_id", "occurred_at" DESC);
CREATE INDEX IF NOT EXISTS "payment_events_order_id_occurred_at_idx" ON "payment_events" ("order_id", "occurred_at");
CREATE INDEX IF NOT EXISTS "payment_events_event_type_occurred_at_idx" ON "payment_events" ("event_type", "occurred_at");
CREATE INDEX IF NOT EXISTS "payment_events_provider_occurred_at_idx" ON "payment_events" ("provider", "occurred_at");
CREATE INDEX IF NOT EXISTS "payment_events_triggered_by_user_id_idx" ON "payment_events" ("triggered_by_user_id");
CREATE UNIQUE INDEX IF NOT EXISTS "payment_events_claim_single_outcome_key" ON "payment_events" ((("details" ->> 'claimId'))) WHERE "event_type" IN ('refund_webhook_absorbed', 'refund_failed');

CREATE TABLE IF NOT EXISTS "payments" (
  "id" TEXT NOT NULL,
  "order_id" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "method" TEXT,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "amount" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "transaction_id" TEXT,
  "invoice_id" TEXT,
  "payment_url" TEXT,
  "refund_id" TEXT,
  "refunded_amount" INTEGER NOT NULL DEFAULT 0,
  "failure_reason" TEXT,
  "paid_at" INTEGER,
  "metadata" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
