CREATE INDEX IF NOT EXISTS "product_model_bindings_store_id_idx" ON "product_model_bindings" ("store_id");
CREATE INDEX IF NOT EXISTS "product_model_bindings_option_value_id_idx" ON "product_model_bindings" ("option_value_id");

