  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "model_url" TEXT NOT NULL,
  "model_bytes" INTEGER NOT NULL,
  "usdz_url" TEXT,
  "usdz_bytes" INTEGER,
  "poster_url" TEXT,
  "alt_text" TEXT,
  "alt_text_ar" TEXT,
  "ar_enabled" INTEGER NOT NULL DEFAULT 1,
  "materials" TEXT NOT NULL DEFAULT '[]',
  "gltf_variants" TEXT NOT NULL DEFAULT '[]',
  "stats" TEXT NOT NULL DEFAULT '{}',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "product_models_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "product_models_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "product_models_ar_enabled_chk" CHECK ("ar_enabled" IN (0, 1)),
  CONSTRAINT "product_models_materials_chk" CHECK (json_valid("materials")),
  CONSTRAINT "product_models_gltf_variants_chk" CHECK (json_valid("gltf_variants")),
  CONSTRAINT "product_models_stats_chk" CHECK (json_valid("stats")),
  CONSTRAINT "product_models_bytes_check" CHECK ("model_bytes" > 0 AND "model_bytes" <= 15728640 AND ("usdz_bytes" IS NULL OR ("usdz_bytes" > 0 AND "usdz_bytes" <= 15728640)))
);
