  "gold_weight_mg" INTEGER,
  "making_charge_type" TEXT,
  "making_charge_value" INTEGER,
  "gold_margin_bps" INTEGER,
  "gold_rate_id" TEXT,
  CONSTRAINT "product_variants_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "product_variants_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "product_variants_is_active_chk" CHECK ("is_active" IN (0, 1)),
  CONSTRAINT "product_variants_allow_backorder_chk" CHECK ("allow_backorder" IN (0, 1)),
  CONSTRAINT "product_variants_pricing_mode_check" CHECK ("pricing_mode" IS NULL OR "pricing_mode" IN ('fixed', 'gold_rate')),
  CONSTRAINT "product_variants_gold_karat_check" CHECK ("gold_karat" IS NULL OR "gold_karat" IN (24, 21, 18)),
  CONSTRAINT "product_variants_gold_weight_check" CHECK ("gold_weight_mg" IS NULL OR "gold_weight_mg" BETWEEN 1 AND 1000000),
  CONSTRAINT "product_variants_making_type_check" CHECK ("making_charge_type" IS NULL OR "making_charge_type" IN ('fixed', 'per_gram')),
  CONSTRAINT "product_variants_making_value_check" CHECK ("making_charge_value" IS NULL OR "making_charge_value" >= 0),
  CONSTRAINT "product_variants_gold_margin_check" CHECK ("gold_margin_bps" IS NULL OR "gold_margin_bps" BETWEEN -5000 AND 10000),
  CONSTRAINT "product_variants_gold_no_compare_check" CHECK ("pricing_mode" IS NOT 'gold_rate' OR "compare_at_price" IS NULL)
);
CREATE INDEX IF NOT EXISTS "product_variants_product_id_idx" ON "product_variants" ("product_id");
CREATE INDEX IF NOT EXISTS "product_variants_sku_idx" ON "product_variants" ("sku");
CREATE INDEX IF NOT EXISTS "product_variants_product_id_barcode_idx" ON "product_variants" (product_id, barcode) WHERE barcode IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "product_variants_product_id_barcode_uniq" ON "product_variants" ("product_id", "barcode") WHERE "barcode" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "products" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "name_ar" TEXT,
  "slug" TEXT NOT NULL,
  "description" TEXT,
  "description_ar" TEXT,
  "search_terms" TEXT,
  "price" INTEGER NOT NULL,
  "moq" INTEGER,
  "audience" TEXT NOT NULL DEFAULT 'public',
  "compare_at_price" INTEGER,
  "cost_price" INTEGER,
  "sku" TEXT,
  "barcode" TEXT,
  "inventory" INTEGER NOT NULL DEFAULT 0,
  "low_stock_threshold" INTEGER NOT NULL DEFAULT 5,
  "track_inventory" INTEGER NOT NULL DEFAULT 1,
  "pricing_mode" TEXT NOT NULL DEFAULT 'fixed',
  "gold_karat" INTEGER,
  "gold_weight_mg" INTEGER,
  "making_charge_type" TEXT,
  "making_charge_value" INTEGER,
  "gold_margin_bps" INTEGER NOT NULL DEFAULT 0,
  "gold_rate_id" TEXT,
  "weight" REAL,
  "dimensions" TEXT,
  "status" TEXT NOT NULL DEFAULT 'draft',
  "featured" INTEGER NOT NULL DEFAULT 0,
  "is_new" INTEGER NOT NULL DEFAULT 0,
  "new_arrival_position" INTEGER NOT NULL DEFAULT 0,
  "is_best_seller" INTEGER NOT NULL DEFAULT 0,
  "best_seller_position" INTEGER NOT NULL DEFAULT 0,
  "badge_label" TEXT,
  "badge_label_ar" TEXT,
  "view_count" INTEGER NOT NULL DEFAULT 0,
  "facts" TEXT NOT NULL DEFAULT '[]',
  "lead_time_days" INTEGER,
  "personalisation" TEXT,
  "size_chart_id" TEXT,
  "excerpt" TEXT,
  "excerpt_ar" TEXT,
  "meta_title" TEXT,
  "meta_title_ar" TEXT,
  "meta_description" TEXT,
  "meta_description_ar" TEXT,
  "meta_description_aeo" TEXT,
  "meta_description_aeo_ar" TEXT,
  "citation_copy" TEXT,
  "citation_copy_ar" TEXT,
  "ai_field_sources" TEXT NOT NULL DEFAULT '{}',
  "ai_balance_backup" TEXT DEFAULT '{}',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "deleted_at" INTEGER,
  "allow_backorder" INTEGER NOT NULL DEFAULT 0,
  "last_cost_update_at" INTEGER,
  "discount_type" TEXT,
  "discount_value" INTEGER,
  "has_variants" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "products_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "products_size_chart_id_fkey" FOREIGN KEY ("size_chart_id") REFERENCES "size_charts" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "products_track_inventory_chk" CHECK ("track_inventory" IN (0, 1)),
  CONSTRAINT "products_dimensions_chk" CHECK ("dimensions" IS NULL OR (json_valid("dimensions"))),
  CONSTRAINT "products_status_chk" CHECK ("status" IN ('draft', 'active', 'archived')),
  CONSTRAINT "products_featured_chk" CHECK ("featured" IN (0, 1)),
  CONSTRAINT "products_is_new_chk" CHECK ("is_new" IN (0, 1)),
  CONSTRAINT "products_is_best_seller_chk" CHECK ("is_best_seller" IN (0, 1)),
  CONSTRAINT "products_facts_chk" CHECK (json_valid("facts")),
  CONSTRAINT "products_personalisation_chk" CHECK ("personalisation" IS NULL OR (json_valid("personalisation"))),
  CONSTRAINT "products_ai_field_sources_chk" CHECK (json_valid("ai_field_sources")),
  CONSTRAINT "products_ai_balance_backup_chk" CHECK ("ai_balance_backup" IS NULL OR (json_valid("ai_balance_backup"))),
  CONSTRAINT "products_allow_backorder_chk" CHECK ("allow_backorder" IN (0, 1)),
  CONSTRAINT "products_discount_type_chk" CHECK ("discount_type" IS NULL OR ("discount_type" IN ('percentage', 'fixed'))),
  CONSTRAINT "products_has_variants_chk" CHECK ("has_variants" IN (0, 1)),
  CONSTRAINT "products_facts_is_array" CHECK (json_type("facts") = 'array'),
  CONSTRAINT "products_lead_time_days_range" CHECK ("lead_time_days" IS NULL OR "lead_time_days" BETWEEN 0 AND 60),
  CONSTRAINT "products_moq_chk" CHECK ("moq" IS NULL OR "moq" >= 2),
  CONSTRAINT "products_audience_chk" CHECK ("audience" IN ('public', 'wholesale_only')),
  CONSTRAINT "products_pricing_mode_check" CHECK ("pricing_mode" IN ('fixed', 'gold_rate')),
  CONSTRAINT "products_gold_karat_check" CHECK ("gold_karat" IS NULL OR "gold_karat" IN (24, 21, 18)),
  CONSTRAINT "products_gold_weight_check" CHECK ("gold_weight_mg" IS NULL OR "gold_weight_mg" BETWEEN 1 AND 1000000),
  CONSTRAINT "products_making_type_check" CHECK ("making_charge_type" IS NULL OR "making_charge_type" IN ('fixed', 'per_gram')),
  CONSTRAINT "products_making_value_check" CHECK ("making_charge_value" IS NULL OR "making_charge_value" >= 0),
  CONSTRAINT "products_gold_margin_check" CHECK ("gold_margin_bps" BETWEEN -5000 AND 10000),
  CONSTRAINT "products_gold_spec_complete_check" CHECK ("pricing_mode" = 'fixed' OR ("gold_karat" IS NOT NULL AND "gold_weight_mg" IS NOT NULL AND "making_charge_type" IS NOT NULL AND "making_charge_value" IS NOT NULL)),
  CONSTRAINT "products_gold_no_compare_check" CHECK ("pricing_mode" = 'fixed' OR "compare_at_price" IS NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS "products_store_id_slug_key" ON "products" ("store_id", "slug");
CREATE INDEX IF NOT EXISTS "products_status_idx" ON "products" ("status");
CREATE INDEX IF NOT EXISTS "products_featured_idx" ON "products" ("featured");
CREATE INDEX IF NOT EXISTS "products_price_idx" ON "products" ("price");
CREATE INDEX IF NOT EXISTS "products_created_at_idx" ON "products" ("created_at");
CREATE INDEX IF NOT EXISTS "products_store_id_status_idx" ON "products" ("store_id", "status");
CREATE INDEX IF NOT EXISTS "products_store_id_is_best_seller_idx" ON "products" ("store_id", "is_best_seller");
CREATE INDEX IF NOT EXISTS "products_store_id_deleted_at_created_at_idx" ON "products" ("store_id", "deleted_at", "created_at" DESC);
CREATE INDEX IF NOT EXISTS "products_size_chart_id_idx" ON "products" ("size_chart_id");
CREATE INDEX IF NOT EXISTS "products_store_id_barcode_idx" ON "products" (store_id, barcode) WHERE barcode IS NOT NULL;
CREATE INDEX IF NOT EXISTS "products_store_id_is_new_new_arrival_position_idx" ON "products" ("store_id", "is_new", "new_arrival_position") WHERE "is_new" = 1;
CREATE INDEX IF NOT EXISTS "products_store_id_is_best_seller_best_seller_position_idx" ON "products" ("store_id", "is_best_seller", "best_seller_position") WHERE "is_best_seller" = 1;
CREATE UNIQUE INDEX IF NOT EXISTS "products_store_id_sku_key" ON "products" ("store_id", "sku") WHERE "deleted_at" IS NULL;
CREATE INDEX IF NOT EXISTS "products_gold_reprice_idx" ON "products" ("store_id", "gold_karat") WHERE "pricing_mode" = 'gold_rate' AND "deleted_at" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "products_store_id_barcode_uniq" ON "products" ("store_id", "barcode") WHERE "barcode" IS NOT NULL AND "deleted_at" IS NULL;

CREATE TABLE IF NOT EXISTS "profit_anomalies" (
  "id" TEXT NOT NULL,
