  "type" TEXT NOT NULL DEFAULT 'return',
  "status" TEXT NOT NULL DEFAULT 'pending',
  "reason" TEXT NOT NULL,
  "reason_detail" TEXT,
  "refund_amount" INTEGER NOT NULL DEFAULT 0,
  "refund_method" TEXT,
  "refunded_at" INTEGER,
  "reversal_requested_at" INTEGER,
  "reversal_applied_at" INTEGER,
  "tracking_number" TEXT,
  "shipped_at" INTEGER,
  "received_at" INTEGER,
  "approved_by" TEXT,
  "approved_at" INTEGER,
  "rejected_by" TEXT,
  "rejected_at" INTEGER,
  "rejection_reason" TEXT,
  "admin_notes" TEXT,
  "customer_notes" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "returns_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "returns_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "returns_type_chk" CHECK ("type" IN ('return', 'exchange', 'refund')),
  CONSTRAINT "returns_status_chk" CHECK ("status" IN ('pending', 'approved', 'rejected', 'shipped', 'received', 'inspecting', 'completed', 'cancelled'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "returns_return_number_key" ON "returns" ("return_number");
CREATE INDEX IF NOT EXISTS "returns_store_id_idx" ON "returns" ("store_id");
CREATE INDEX IF NOT EXISTS "returns_order_id_idx" ON "returns" ("order_id");
CREATE INDEX IF NOT EXISTS "returns_customer_id_idx" ON "returns" ("customer_id");
CREATE INDEX IF NOT EXISTS "returns_status_idx" ON "returns" ("status");
CREATE INDEX IF NOT EXISTS "returns_created_at_idx" ON "returns" ("created_at");
CREATE INDEX IF NOT EXISTS "returns_reversal_pending_idx" ON "returns" ("reversal_requested_at") WHERE "reversal_applied_at" IS NULL AND "reversal_requested_at" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "reviews" (
