-- Store split (task 1.4): commerce, flags, integrations, accounting and AI switches. One row.
CREATE TABLE IF NOT EXISTS "store_config" (
  "store_id" TEXT NOT NULL,
  "settings" TEXT NOT NULL DEFAULT '{}',
  "tax_enabled" INTEGER NOT NULL DEFAULT 0,
  "tax_included_in_price" INTEGER NOT NULL DEFAULT 0,
  "default_tax_rate" INTEGER,
  "loyalty_enabled" INTEGER NOT NULL DEFAULT 0,
  "loyalty_settings" TEXT NOT NULL DEFAULT '{}',
  "pwa_enabled" INTEGER NOT NULL DEFAULT 0,
  "pwa_settings" TEXT NOT NULL DEFAULT '{}',
  "blog_enabled" INTEGER NOT NULL DEFAULT 0,
  "locations_enabled" INTEGER NOT NULL DEFAULT 0,
  "agent_api_key_rotated_at" INTEGER,
  "return_window_days" INTEGER,
  "return_fees_paid_by" TEXT,
  "accounting_enabled" INTEGER NOT NULL DEFAULT 1,
  "default_tax_rate_bps" INTEGER NOT NULL DEFAULT 0,
  "fiscal_year_start_month" INTEGER NOT NULL DEFAULT 1,
  "expense_two_step_approval" INTEGER NOT NULL DEFAULT 0,
  "ai_features_enabled" INTEGER NOT NULL DEFAULT 1,
  "ai_bulk_throttle_ms" INTEGER NOT NULL DEFAULT 2500,
  "ai_narration_enabled" INTEGER NOT NULL DEFAULT 1,
  "insights_rollup_cron" TEXT NOT NULL DEFAULT 'daily',
  "ci_sharing" INTEGER NOT NULL DEFAULT 0,
  "ci_sharing_changed_at" INTEGER,
  CONSTRAINT "store_config_pkey" PRIMARY KEY ("store_id"),
  CONSTRAINT "store_config_settings_chk" CHECK (json_valid("settings")),
  CONSTRAINT "store_config_tax_enabled_chk" CHECK ("tax_enabled" IN (0, 1)),
  CONSTRAINT "store_config_tax_included_in_price_chk" CHECK ("tax_included_in_price" IN (0, 1)),
  CONSTRAINT "store_config_loyalty_enabled_chk" CHECK ("loyalty_enabled" IN (0, 1)),
  CONSTRAINT "store_config_loyalty_settings_chk" CHECK (json_valid("loyalty_settings")),
  CONSTRAINT "store_config_pwa_enabled_chk" CHECK ("pwa_enabled" IN (0, 1)),
  CONSTRAINT "store_config_pwa_settings_chk" CHECK (json_valid("pwa_settings")),
  CONSTRAINT "store_config_blog_enabled_chk" CHECK ("blog_enabled" IN (0, 1)),
  CONSTRAINT "store_config_locations_enabled_chk" CHECK ("locations_enabled" IN (0, 1)),
  CONSTRAINT "store_config_accounting_enabled_chk" CHECK ("accounting_enabled" IN (0, 1)),
  CONSTRAINT "store_config_expense_two_step_approval_chk" CHECK ("expense_two_step_approval" IN (0, 1)),
  CONSTRAINT "store_config_ai_features_enabled_chk" CHECK ("ai_features_enabled" IN (0, 1)),
  CONSTRAINT "store_config_ai_narration_enabled_chk" CHECK ("ai_narration_enabled" IN (0, 1)),
  CONSTRAINT "store_config_ci_sharing_chk" CHECK ("ci_sharing" IN (0, 1)),
  CONSTRAINT "stores_fiscal_year_start_month_range" CHECK (fiscal_year_start_month BETWEEN 1 AND 12)
);

