  "maps_embed_url" TEXT,
  "hours" TEXT,
  "hours_ar" TEXT,
  "is_published" INTEGER NOT NULL DEFAULT 1,
  "position" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "store_locations_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "store_locations_is_published_chk" CHECK ("is_published" IN (0, 1))
);
CREATE INDEX IF NOT EXISTS "store_locations_store_id_is_published_position_idx" ON "store_locations" ("store_id", "is_published", "position");

CREATE TABLE IF NOT EXISTS "store_page_revisions" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "page_key" TEXT NOT NULL,
  "rev" INTEGER NOT NULL,
  "status" TEXT NOT NULL,
  "schema_version" INTEGER NOT NULL,
  "document" TEXT NOT NULL,
  "doc_bytes" INTEGER NOT NULL,
  "base_rev" INTEGER,
  "note" TEXT,
  "created_by" TEXT,
  "published_by" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "published_at" INTEGER,
  CONSTRAINT "store_page_revisions_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "store_page_revisions_document_chk" CHECK (json_valid("document")),
  CONSTRAINT "store_page_revisions_status_check" CHECK ("status" IN ('draft', 'published', 'archived')),
  CONSTRAINT "store_page_revisions_rev_check" CHECK ("rev" >= 1),
  CONSTRAINT "store_page_revisions_doc_bytes_check" CHECK ("doc_bytes" >= 0 AND "doc_bytes" <= 262144),
  CONSTRAINT "store_page_revisions_page_key_check" CHECK ((length("page_key") BETWEEN 1 AND 64 AND "page_key" GLOB '[a-z0-9]*' AND "page_key" NOT GLOB '*[^a-z0-9-]*'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "store_page_revisions_store_id_page_key_rev_key" ON "store_page_revisions" ("store_id", "page_key", "rev");
CREATE INDEX IF NOT EXISTS "store_page_revisions_store_id_page_key_created_at_idx" ON "store_page_revisions" ("store_id", "page_key", "created_at" DESC);
CREATE UNIQUE INDEX IF NOT EXISTS "store_page_revisions_one_published" ON "store_page_revisions" ("store_id", "page_key") WHERE "status" = 'published';
CREATE UNIQUE INDEX IF NOT EXISTS "store_page_revisions_one_draft" ON "store_page_revisions" ("store_id", "page_key") WHERE "status" = 'draft';

CREATE TABLE IF NOT EXISTS "store_pages" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "title" TEXT,
  "title_ar" TEXT,
  "content_blocks" TEXT,
  "content_blocks_ar" TEXT,
  "cover_image" TEXT,
  "is_published" INTEGER NOT NULL DEFAULT 1,
  "position" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "store_pages_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "store_pages_content_blocks_chk" CHECK ("content_blocks" IS NULL OR (json_valid("content_blocks"))),
  CONSTRAINT "store_pages_content_blocks_ar_chk" CHECK ("content_blocks_ar" IS NULL OR (json_valid("content_blocks_ar"))),
  CONSTRAINT "store_pages_is_published_chk" CHECK ("is_published" IN (0, 1))
);
CREATE UNIQUE INDEX IF NOT EXISTS "store_pages_store_id_slug_key" ON "store_pages" ("store_id", "slug");
CREATE INDEX IF NOT EXISTS "store_pages_store_id_idx" ON "store_pages" ("store_id");

-- Store split (task 1.4): D1 mirror fields (write-through) plus branding, content, SEO, contact and pixels. One row, id = the DO store id.
CREATE TABLE IF NOT EXISTS "store_profile" (
  "store_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "name_ar" TEXT,
  "slug" TEXT NOT NULL,
  "domain" TEXT,
  "owner_id" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'active',
  "plan" TEXT NOT NULL DEFAULT 'starter',
  "logo" TEXT,
  "logo_ar" TEXT,
  "favicon" TEXT,
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "timezone" TEXT NOT NULL DEFAULT 'Africa/Cairo',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "template" TEXT NOT NULL DEFAULT 'qamar',
  "look" TEXT,
  "is_demo" INTEGER NOT NULL DEFAULT 0,
  "hero_title" TEXT,
  "hero_title_ar" TEXT,
  "hero_subtitle" TEXT,
  "hero_subtitle_ar" TEXT,
  "hero_cta_text" TEXT,
  "hero_cta_text_ar" TEXT,
  "hero_cta_link" TEXT,
  "hero_image" TEXT,
  "best_sellers_image" TEXT,
  "typography" TEXT,
  "description" TEXT,
  "description_ar" TEXT,
  "theme" TEXT NOT NULL DEFAULT '{}',
  "layout_settings" TEXT NOT NULL DEFAULT '{}',
  "social_links" TEXT NOT NULL DEFAULT '{}',
  "email" TEXT,
  "phone" TEXT,
  "phone_ar" TEXT,
  "whatsapp" TEXT,
  "address" TEXT,
  "address_ar" TEXT,
  "business_hours" TEXT,
  "google_maps_url" TEXT,
  "announcement_bar" TEXT,
  "meta_title" TEXT,
  "meta_title_ar" TEXT,
  "meta_description" TEXT,
  "meta_description_ar" TEXT,
  "meta_description_aeo" TEXT,
  "meta_description_aeo_ar" TEXT,
  "og_image" TEXT,
  "twitter_handle" TEXT,
  "google_site_verification" TEXT,
  "marketing_pixels" TEXT NOT NULL DEFAULT '{}',
  "meta_pixel_id" TEXT,
  "tiktok_pixel_id" TEXT,
  "snapchat_pixel_id" TEXT,
  "google_analytics_id" TEXT,
  "google_tag_manager_id" TEXT,
  "google_ads_id" TEXT,
  "twitter_pixel_id" TEXT,
  "pinterest_tag_id" TEXT,
  "llms_txt" TEXT,
  "about_json" TEXT,
  CONSTRAINT "store_profile_pkey" PRIMARY KEY ("store_id"),
  CONSTRAINT "store_profile_status_chk" CHECK ("status" IN ('active', 'inactive', 'suspended')),
  CONSTRAINT "store_profile_plan_chk" CHECK ("plan" IN ('free', 'starter', 'professional', 'enterprise')),
  CONSTRAINT "store_profile_template_chk" CHECK ("template" IN ('modern', 'classic', 'minimal', 'bold', 'elegant', 'dahab', 'qamar', 'souq', 'jasmine', 'lamma')),
  CONSTRAINT "store_profile_is_demo_chk" CHECK ("is_demo" IN (0, 1)),
  CONSTRAINT "store_profile_typography_chk" CHECK ("typography" IS NULL OR (json_valid("typography"))),
  CONSTRAINT "store_profile_theme_chk" CHECK (json_valid("theme")),
  CONSTRAINT "store_profile_layout_settings_chk" CHECK (json_valid("layout_settings")),
  CONSTRAINT "store_profile_social_links_chk" CHECK (json_valid("social_links")),
  CONSTRAINT "store_profile_announcement_bar_chk" CHECK ("announcement_bar" IS NULL OR (json_valid("announcement_bar"))),
  CONSTRAINT "store_profile_marketing_pixels_chk" CHECK (json_valid("marketing_pixels")),
  CONSTRAINT "store_profile_about_json_chk" CHECK ("about_json" IS NULL OR (json_valid("about_json"))),
  CONSTRAINT "stores_look_format" CHECK ("look" IS NULL OR ("look" GLOB '*.*' AND "look" NOT GLOB '*.*.*' AND "look" NOT GLOB '*[^a-z.]*' AND "look" NOT GLOB '*.' AND substr("look", 1, instr("look", '.') - 1) IN ('qamar', 'souq', 'jasmine', 'lamma', 'dahab')))
);

CREATE TABLE IF NOT EXISTS "store_tax_documents" (
  "id" TEXT NOT NULL,
