);
CREATE INDEX IF NOT EXISTS "wholesale_applications_store_id_status_created_at_idx" ON "wholesale_applications" ("store_id", "status", "created_at");
CREATE INDEX IF NOT EXISTS "wholesale_applications_user_id_idx" ON "wholesale_applications" ("user_id");
CREATE INDEX IF NOT EXISTS "wholesale_applications_group_id_idx" ON "wholesale_applications" ("group_id");
CREATE INDEX IF NOT EXISTS "wholesale_applications_store_id_group_id_idx" ON "wholesale_applications" ("store_id", "group_id");
CREATE UNIQUE INDEX IF NOT EXISTS "wholesale_applications_one_pending_key" ON "wholesale_applications" ("store_id", "user_id") WHERE "status" = 'pending';

CREATE TABLE IF NOT EXISTS "wishlist_items" (
  "id" TEXT NOT NULL,
  "wishlist_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "added_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "wishlist_items_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "wishlist_items_wishlist_id_fkey" FOREIGN KEY ("wishlist_id") REFERENCES "wishlists" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "wishlist_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "wishlist_items_wishlist_id_product_id_key" ON "wishlist_items" ("wishlist_id", "product_id");
CREATE INDEX IF NOT EXISTS "wishlist_items_product_id_idx" ON "wishlist_items" ("product_id");

CREATE TABLE IF NOT EXISTS "wishlists" (
  "id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "name" TEXT NOT NULL DEFAULT 'My Wishlist',
  "is_public" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "wishlists_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "wishlists_is_public_chk" CHECK ("is_public" IN (0, 1))
);
CREATE UNIQUE INDEX IF NOT EXISTS "wishlists_user_id_store_id_key" ON "wishlists" ("user_id", "store_id");
CREATE INDEX IF NOT EXISTS "wishlists_user_id_idx" ON "wishlists" ("user_id");
CREATE INDEX IF NOT EXISTS "wishlists_store_id_idx" ON "wishlists" ("store_id");
